createPromise = () => {\n        let resolve: (value: Value) => void = noop;\n        let reject: (reason?: any) => void = noop;\n        const promise = new Promise<Value>((res, rej) => {\n            resolve = res;\n            reject = rej;\n        });\n        promiseRef.current = { promise, resolve, reject };\n        return promise;\n    };\n\n    const handleShowModal = (ownProps: OwnProps) => {\n        setOwnProps(ownProps);\n        setOpen(true);\n        return createPromise();\n    };\n\n    const handleResolve = (value: Value) => {\n        promiseRef.current?.resolve(value);\n        props.onClose();\n    };\n\n    const handleReject = (reason?: any) => {\n        promiseRef.current?.reject(reason);\n        props.onClose();\n    };\n\n    const promiseHandlers = usePromise ? { onResolve: handleResolve, onReject: handleReject } : {};\n\n    const modal = render ? <Modal {...props} {...ownProps} {...promiseHandlers} /> : null;\n\n    return [modal, handleShowModal];\n};\n","import { useRef } from 'react';\n\nimport usePopperState from './usePopperState';\n\nconst usePopperAnchor = <T>(onChange?: (state: boolean) => void) => {\n    const ref = useRef<T>(null);\n    const state = usePopperState(onChange);\n    return { ...state, anchorRef: ref };\n};\n\nexport default usePopperAnchor;\n","import { useCallback, useState } from 'react';\n\nimport useIsMounted from '@proton/hooks/useIsMounted';\n\nconst usePopperState = (onChange?: (state: boolean) => void) => {\n    const [isOpen, setOpen] = useState(false);\n    const isMounted = useIsMounted();\n\n    const open = useCallback(() => {\n        // setState should not occur when the component is unmounted\n        if (isMounted()) {\n            setOpen(true);\n        }\n        onChange?.(true);\n    }, []);\n\n    const close = useCallback(() => {\n        // setState should not occur when the component is unmounted\n        if (isMounted()) {\n            setOpen(false);\n        }\n        onChange?.(false);\n    }, []);\n\n    const toggle = useCallback(() => {\n        return isOpen ? close() : open();\n    }, [isOpen]);\n\n    return { isOpen, toggle, open, close };\n};\n\nexport default usePopperState;\n","import { DetailedHTMLProps, OptionHTMLAttributes, Ref, SelectHTMLAttributes, forwardRef, useState } from 'react';\n\nimport { classnames, generateUID } from '../../helpers';\nimport Icon from '../icon/Icon';\nimport useInput from '../input/useInput';\nimport ErrorZone from '../text/ErrorZone';\n\nexport interface OptionProps extends DetailedHTMLProps<OptionHTMLAttributes<HTMLOptionElement>, HTMLOptionElement> {\n    value: string | number;\n    text: string | number;\n    group?: string;\n    disabled?: boolean;\n}\n\nconst buildOptions = (options: OptionProps[] = [], keyPrefix = 'option') => {\n    return options.map(({ text, ...rest }, index) => (\n        <option key={`${keyPrefix}_${index}`} {...rest}>\n            {text}\n        </option>\n    ));\n};\n\nconst buildGroupedOptions = (options: OptionProps[] = []) => {\n    const orphanOptions = options.filter((o: OptionProps) => !o.group);\n\n    return (\n        <>\n            {buildOptions(orphanOptions)}\n            {Object.entries(\n                options.reduce<{ [key: string]: OptionProps[] }>((acc, option) => {\n                    if (!option.group) {\n                        return acc;\n                    }\n\n                    const { group } = option;\n                    acc[group] = acc[group] || [];\n                    acc[group].push(option);\n                    return acc;\n                }, {})\n            ).map(([group, options], index) => {\n                return (\n                    <optgroup key={`optionGroup_${index}`} label={group}>\n                        {buildOptions(options, `optionGroup_${index}`)}\n                    </optgroup>\n                );\n            })}\n        </>\n    );\n};\n\nexport interface Props extends DetailedHTMLProps<SelectHTMLAttributes<HTMLSelectElement>, HTMLSelectElement> {\n    ref?: Ref<HTMLSelectElement>; // override ref so that LegacyRef isn't used\n    error?: string;\n    isSubmitted?: boolean;\n    size?: number;\n    options: OptionProps[];\n    loading?: boolean;\n    classNameContainer?: string;\n}\n\n/**\n * @deprecated please use SelectTwo instead\n */\nconst Select = forwardRef<HTMLSelectElement, Props>(\n    (\n        {\n            options,\n            error,\n            size = 1,\n            className = '',\n            multiple = false,\n            loading = false,\n            isSubmitted = false,\n            classNameContainer,\n            ...rest\n        }: Props,\n        ref\n    ) => {\n        const { handlers, statusClasses, status } = useInput<HTMLSelectElement>(rest);\n        const [uid] = useState(generateUID('select'));\n        const hasError = error && (status.isDirty || isSubmitted);\n        const hasGroup = options.some(({ group }) => group);\n\n        return (\n            <>\n                <span className={classnames(['w100 flex flex-column', classNameContainer])}>\n                    <span className=\"flex relative w100\">\n                        <select\n                            className={classnames(['field w100', className, statusClasses])}\n                            size={size}\n                            multiple={multiple}\n                            disabled={loading || rest.disabled}\n                            ref={ref}\n                            {...rest}\n                            {...handlers}\n                        >\n                            {hasGroup ? buildGroupedOptions(options) : buildOptions(options)}\n                        </select>\n                        <Icon name=\"chevron-down-filled\" className=\"absolute no-pointer-events right-icon\" />\n                    </span>\n\n                    {hasError && <ErrorZone id={uid}>{error}</ErrorZone>}\n                </span>\n            </>\n        );\n    }\n);\n\nexport default Select;\n","import { DARK_THEMES } from '@proton/shared/lib/themes/themes';\n\nimport { useTheme } from './ThemeProvider';\n\nconst useIsDarkTheme = () => {\n    const [theme] = useTheme();\n    return DARK_THEMES.includes(theme);\n};\n\nexport default useIsDarkTheme;\n","import { SenderImageMode, getLogo } from '@proton/shared/lib/api/images';\nimport { createUrl } from '@proton/shared/lib/fetch/helpers';\nimport { Api } from '@proton/shared/lib/interfaces';\n\nconst CACHE = {} as { [domain: string]: Promise<string> };\n\nconst fetchSenderLogo = async (\n    api: Api,\n    emailAddress: string,\n    size?: number,\n    bimiSelector?: string,\n    mode?: SenderImageMode\n) => {\n    try {\n        const response: Response = await api({\n            ...getLogo(emailAddress, size, bimiSelector, mode),\n            output: 'raw',\n            silence: true,\n        });\n\n        return URL.createObjectURL(await response.blob());\n    } catch (error) {\n        return '';\n    }\n};\n\nexport const getSenderLogo = (\n    api: Api,\n    emailAddress: string,\n    size?: number,\n    bimiSelector?: string,\n    mode?: SenderImageMode\n): Promise<string> => {\n    if (typeof CACHE[emailAddress] === 'undefined') {\n        CACHE[emailAddress] = fetchSenderLogo(api, emailAddress, size, bimiSelector, mode);\n    }\n\n    return CACHE[emailAddress];\n};\n\nexport const getImageSize = () => {\n    if (window.devicePixelRatio >= 4) {\n        return 128;\n    }\n\n    if (window.devicePixelRatio > 1) {\n        return 64;\n    }\n\n    return 32;\n};\n\nexport const getSenderImageUrl = (\n    UID: string,\n    emailAddress: string,\n    size?: number,\n    bimiSelector?: string,\n    mode?: SenderImageMode\n) => {\n    const config = getLogo(emailAddress, size, bimiSelector, mode, UID);\n    const prefixedUrl = `api/${config.url}`; // api/ is required to set the AUTH cookie\n    const url = createUrl(prefixedUrl, config.params);\n    return url.toString();\n};\n","import { useEffect, useRef, useState } from 'react';\n\nimport { useIsDarkTheme } from '@proton/components';\nimport { useApi, useAuthentication, useMailSettings } from '@proton/components/hooks';\n\nimport { getImageSize, getSenderImageUrl, getSenderLogo } from '../helpers/senderImage';\n\n/**\n * Return the sender image for a given email address\n * @param emailAddress email address to get the sender image for\n * @returns the sender image\n */\nconst useSenderImage = (emailAddress: string, fallback: boolean, bimiSelector?: string) => {\n    const [mailSettings] = useMailSettings();\n    const isDarkTheme = useIsDarkTheme();\n    const imageSizeRef = useRef(getImageSize());\n    const mode = isDarkTheme ? 'dark' : 'light';\n    const api = useApi();\n    const { UID } = useAuthentication();\n    const [url, setUrl] = useState('');\n    const [canLoad, setCanLoad] = useState(false);\n\n    useEffect(() => {\n        setCanLoad(!!emailAddress && mailSettings?.HideSenderImages === 0);\n    }, [emailAddress, mailSettings?.HideSenderImages]);\n\n    useEffect(() => {\n        if (!canLoad) {\n            return;\n        }\n\n        if (fallback) {\n            // Load the image with XHR request and create a blob URL\n            void getSenderLogo(api, emailAddress, imageSizeRef.current, bimiSelector, mode).then((fallbackUrl) => {\n                // Fallback URL can be empty if the network request fails\n                if (fallbackUrl.length) {\n                    setUrl(fallbackUrl);\n                } else {\n                    // In that case, we cannot load an image (and fallback to initials)\n                    setCanLoad(false);\n                }\n            });\n            return;\n        }\n\n        // Load the image with a simple GET request\n        setUrl(getSenderImageUrl(UID, emailAddress, imageSizeRef.current, bimiSelector, mode));\n    }, [emailAddress, canLoad, mode, bimiSelector, fallback]);\n\n    return { canLoad, url };\n};\n\nexport default useSenderImage;\n","import { useState } from 'react';\n\nimport 'intersection-observer';\n\nimport { getInitials } from '@proton/shared/lib/helpers/string';\nimport clsx from '@proton/utils/clsx';\n\nimport useSenderImage from './hooks/useSenderImage';\n\ninterface Props {\n    email: string;\n    name: string;\n    className?: string;\n    bimiSelector?: string;\n}\n\nconst ContactImage = ({ email, name, className, bimiSelector }: Props) => {\n    const [fallback, setFallback] = useState(false);\n    const { canLoad, url } = useSenderImage(email, fallback, bimiSelector);\n\n    if (canLoad) {\n        // Fallback to XHR API call to load the image if native fails\n        const handleError = () => {\n            // url is not set at the initial render\n            if (!url) {\n                return;\n            }\n            setFallback(true);\n        };\n\n        return (\n            <img\n                className={clsx(className, 'item-sender-image')}\n                alt=\"\"\n                width=\"32\"\n                src={url}\n                onError={handleError}\n                loading=\"lazy\" // Lazy load the image only when it's in the viewport\n                data-testid=\"contact-image\"\n            />\n        );\n    }\n\n    return <span data-testid=\"contact-initials\">{getInitials(name)}</span>;\n};\n\nexport default ContactImage;\n","import { c } from 'ttag';\n\nimport { APPS_CONFIGURATION } from '@proton/shared/lib/constants';\n\nimport { InlineLinkButton } from '../../components';\nimport { useConfig } from '../../hooks';\nimport useApiStatus from '../../hooks/useApiStatus';\nimport TopBanner from './TopBanner';\n\nconst BadAppVersionBanner = () => {\n    const { APP_NAME } = useConfig();\n    const { appVersionBad } = useApiStatus();\n\n    if (!appVersionBad) {\n        return null;\n    }\n\n    const appName = APPS_CONFIGURATION[APP_NAME].name;\n    const reload = () => window.location.reload();\n    const reloadButton = (\n        <InlineLinkButton key=\"reload-button\" className=\"color-inherit\" onClick={reload}>{c('Action')\n            .t`Refresh the page`}</InlineLinkButton>\n    );\n\n    return (\n        <TopBanner className=\"bg-danger\">\n            {c('Message display when a new app version is available')\n                .jt`A new version of ${appName} is available. ${reloadButton}.`}\n        </TopBanner>\n    );\n};\n\nexport default BadAppVersionBanner;\n","export const ping = () => ({\n    url: 'tests/ping',\n    method: 'get',\n});\n\nexport const testHumanVerification = () => ({\n    url: 'tests/humanverification',\n    method: 'get',\n});\n","import { useEffect, useRef, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { ping } from '@proton/shared/lib/api/tests';\nimport noop from '@proton/utils/noop';\n\nimport { useDebounceInput } from '../../components';\nimport { useOnline } from '../../hooks';\nimport useApi from '../../hooks/useApi';\nimport useApiStatus from '../../hooks/useApiStatus';\nimport TopBanner from './TopBanner';\n\nconst OFFLINE_TIMEOUT = 5000;\n\nconst OnlineTopBanner = () => {\n    const { apiUnreachable, offline } = useApiStatus();\n    const onlineStatus = useOnline();\n    const safeOnlineStatusValue = onlineStatus && !offline;\n    const safeOnlineStatus = useDebounceInput(safeOnlineStatusValue, safeOnlineStatusValue ? 0 : OFFLINE_TIMEOUT);\n    const api = useApi();\n\n    const oldRef = useRef(safeOnlineStatus);\n    const [backOnline, setBackOnline] = useState(false);\n\n    useEffect(() => {\n        if (oldRef.current === safeOnlineStatus) {\n            return;\n        }\n        oldRef.current = safeOnlineStatus;\n\n        const handlePing = () => {\n            // Ping can only be used to resolve if the client can establish a connection to the API.\n            api(ping()).catch(noop);\n        };\n\n        if (!safeOnlineStatus) {\n            const handle = window.setInterval(() => {\n                handlePing();\n            }, 5000);\n            return () => window.clearInterval(handle);\n        }\n\n        setBackOnline(true);\n\n        const handle = window.setTimeout(() => {\n            setBackOnline(false);\n            // Ensure it's true\n            handlePing();\n        }, 2000);\n\n        return () => window.clearTimeout(handle);\n    }, [safeOnlineStatus]);\n\n    if (safeOnlineStatus && backOnline) {\n        return <TopBanner className=\"bg-success\">{c('Info').t`Internet connection restored.`}</TopBanner>;\n    }\n\n    if (safeOnlineStatus) {\n        // If the device is known to be online, and the API is unreachable\n        if (apiUnreachable) {\n            return <TopBanner className=\"bg-danger\">{apiUnreachable}</TopBanner>;\n        }\n        return null;\n    }\n\n    // If the device is known to be offline, the API unreachable is not displayed.\n    return (\n        <TopBanner className=\"bg-danger\">{c('Info')\n            .t`Internet connection lost. Please check your device's connectivity.`}</TopBanner>\n    );\n};\n\nexport default OnlineTopBanner;\n","import { ReactNode } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\n\nimport Icon from '../../components/icon/Icon';\nimport { classnames } from '../../helpers';\n\ninterface Props {\n    children: ReactNode;\n    className?: string;\n    onClose?: () => void;\n}\n\nconst TopBanner = ({ children, className, onClose }: Props) => {\n    return (\n        <div\n            role=\"alert\"\n            className={classnames([\n                'flex flex-item-noshrink flex-nowrap text-center relative text-bold no-print',\n                className,\n            ])}\n        >\n            <div className=\"flex-item-fluid p0-5\">{children}</div>\n            {onClose ? (\n                <Button\n                    icon\n                    shape=\"ghost\"\n                    className=\"flex-item-noshrink rounded-none\"\n                    onClick={onClose}\n                    title={c('Action').t`Close this banner`}\n                >\n                    <Icon name=\"cross\" alt={c('Action').t`Close this banner`} />\n                </Button>\n            ) : null}\n        </div>\n    );\n};\n\nexport default TopBanner;\n","export const getAppVersion = (versionString: string) => {\n    return versionString.replace(/-beta.(\\d+)/, ' - Beta $1');\n};\n","import { useCallback } from 'react';\n\nimport { LabelCount } from '@proton/shared/lib/interfaces/Label';\nimport { ConversationCountsModel } from '@proton/shared/lib/models/conversationCountsModel';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult, { getPromiseValue } from './useCachedModelResult';\n\nexport const useGetConversationCounts = (): (() => Promise<LabelCount[]>) => {\n    const api = useApi();\n    const cache = useCache();\n    const miss = useCallback(() => ConversationCountsModel.get(api), [api]);\n    return useCallback(() => {\n        return getPromiseValue(cache, ConversationCountsModel.key, miss);\n    }, [cache, miss]);\n};\n\nexport const useConversationCounts = (): [LabelCount[], boolean, any] => {\n    const cache = useCache();\n    const miss = useGetConversationCounts();\n    return useCachedModelResult(cache, ConversationCountsModel.key, miss);\n};\n","import React from 'react';\n\nimport { c } from 'ttag';\n\nimport { isEdge, isIE11 } from '@proton/shared/lib/helpers/browser';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport { Checkbox } from '../../input';\nimport { Label } from '../../label';\nimport { Href } from '../../link';\n\ninterface Props {\n    link: string;\n    isPunnyCoded: boolean;\n    value: boolean;\n    onToggle: () => void;\n    isOutside: boolean;\n}\n\nconst LinkConfirmationModalLink = ({ link, isPunnyCoded, value, onToggle, isOutside = false }: Props) => {\n    const isMSBrowser = isEdge() || isIE11();\n\n    return (\n        <>\n            {`${c('Info').t`You are about to open another browser tab and visit:`} `}\n            <span className=\"text-bold text-break\">{link}</span>\n\n            {isPunnyCoded && (\n                <>\n                    {isMSBrowser\n                        ? c('Info')\n                              .t`This link may be a homograph attack and cannot be opened by the Edge browser. If you are certain the link is legitimate, please use a different browser to open it.`\n                        : c('Info')\n                              .t`This link may be a homograph attack. Please verify this is the link you wish to visit, or don't open it.`}\n                    <Href url={getKnowledgeBaseUrl('/homograph-attacks')} title=\"What are homograph attacks?\">\n                        {c('Info').t`Learn more`}\n                    </Href>\n                </>\n            )}\n\n            {!isOutside && (\n                <Label className=\"flex\">\n                    <Checkbox checked={value} onChange={onToggle} className=\"mr0-5\" />\n                    {c('Label').t`Do not ask again`}\n                </Label>\n            )}\n        </>\n    );\n};\n\nexport default LinkConfirmationModalLink;\n","import React from 'react';\n\nimport { c } from 'ttag';\n\nimport { Checkbox } from '../../input';\nimport { Label } from '../../label';\n\ninterface Props {\n    link: string;\n    value: boolean;\n    onToggle: () => void;\n}\n\nconst LinkConfirmationModalPhishing = ({ link, onToggle, value }: Props) => (\n    <>\n        {`${c('Info')\n            .t`This link leads to a website that might be trying to steal your information, such as passwords and credit card details.`} `}\n        <br />\n        <span className=\"text-bold text-break\">{link}</span>\n\n        <Label className=\"flex\">\n            <Checkbox className=\"mr0-5\" checked={value} onChange={onToggle} />\n            {c('Label').t`I understand the risk`}\n        </Label>\n    </>\n);\n\nexport default LinkConfirmationModalPhishing;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { updateConfirmLink } from '@proton/shared/lib/api/mailSettings';\nimport { openNewTab } from '@proton/shared/lib/helpers/browser';\nimport { rtlSanitize } from '@proton/shared/lib/helpers/string';\n\nimport { useApi, useEventManager } from '../../../hooks';\nimport { Form } from '../../form';\nimport { ModalProps, ModalStateProps, ModalTwo, ModalTwoContent, ModalTwoFooter, ModalTwoHeader } from '../../modalTwo';\nimport LinkConfirmationModalLink from './LinkConfirmationModalLink';\nimport LinkConfirmationModalPhishing from './LinkConfirmationModalPhishing';\n\ninterface Props extends ModalProps {\n    link?: string;\n    isOutside?: boolean;\n    isPhishingAttempt?: boolean;\n    modalProps: ModalStateProps;\n}\n\nconst LinkConfirmationModal = ({ link = '', isOutside = false, isPhishingAttempt = false, modalProps }: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const [dontAskAgain, setDontAskAgain] = useState(false);\n    const [understandRisk, setUnderstandRisk] = useState(false);\n\n    // https://jira.protontech.ch/browse/SEC-574\n    const linkToShow = rtlSanitize(link);\n\n    // Both are not able to open the link\n    const isPunnyCodeLink = /:\\/\\/xn--/.test(link);\n\n    const handleConfirm = async () => {\n        openNewTab(link);\n\n        if (dontAskAgain && !isOutside) {\n            await api(updateConfirmLink(0));\n            await call();\n        }\n\n        modalProps.onClose();\n    };\n\n    return (\n        <ModalTwo size=\"large\" as={Form} onSubmit={handleConfirm} {...modalProps}>\n            <ModalTwoHeader\n                title={\n                    isPhishingAttempt ? c('Title').t`Warning: suspected fake website` : c('Title').t`Link confirmation`\n                }\n            />\n            <ModalTwoContent>\n                {isPhishingAttempt ? (\n                    <LinkConfirmationModalPhishing\n                        link={linkToShow}\n                        onToggle={() => setUnderstandRisk(!understandRisk)}\n                        value={understandRisk}\n                    />\n                ) : (\n                    <LinkConfirmationModalLink\n                        value={dontAskAgain}\n                        isOutside={isOutside}\n                        isPunnyCoded={isPunnyCodeLink}\n                        link={linkToShow}\n                        onToggle={() => setDontAskAgain(!dontAskAgain)}\n                    />\n                )}\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                <Button onClick={modalProps.onClose}>{c('Action').t`Cancel`}</Button>\n                {/* translator: this string is only for blind people, it will be vocalized: confirm opening of link https://link.com */}\n                <Button\n                    color=\"norm\"\n                    type=\"submit\"\n                    autoFocus\n                    aria-label={c('Action').t`Confirm opening of link ${linkToShow}`}\n                    disabled={isPhishingAttempt && !understandRisk}\n                >\n                    {c('Action').t`Confirm`}\n                </Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default LinkConfirmationModal;\n","import { ReactNode, RefObject, useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { PROTON_DOMAINS } from '@proton/shared/lib/constants';\nimport { getSecondLevelDomain } from '@proton/shared/lib/helpers/url';\nimport { MailSettings } from '@proton/shared/lib/interfaces';\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport { useModalState } from '../components';\nimport LinkConfirmationModal from '../components/notifications/LinkConfirmationModal/LinkConfirmationModal';\nimport { getHostname, isExternal, isSubDomain, punycodeUrl } from '../helpers/url';\nimport { useHandler, useNotifications } from './index';\n\n// Reference : Angular/src/app/utils/directives/linkHandler.js\n\ninterface UseLinkHandlerOptions {\n    onMailTo?: (src: string) => void;\n    startListening?: boolean;\n    isOutside?: boolean;\n    isPhishingAttempt?: boolean;\n}\ntype UseLinkHandler = (\n    wrapperRef: RefObject<HTMLDivElement | undefined>,\n    mailSettings?: MailSettings,\n    options?: UseLinkHandlerOptions\n) => { modal: ReactNode };\n\nconst defaultOptions: UseLinkHandlerOptions = {\n    startListening: true,\n};\n\nconst getSrc = (target: Element) => {\n    const extract = () => {\n        try {\n            return { encoded: target.toString() || '', raw: target.getAttribute('href') || '' };\n        } catch (e: any) {\n            /*\n                Because for Edge/IE11\n                <a href=\"http://xn--rotonmail-4sg.com\" rel=\"noreferrer nofollow noopener\">Protonmail.com</a>\n                will crash --> Unspecified error. ¯\\_(ツ)_/¯\n                Don't worry, target.href/getAttribute will crash too ¯\\_(ツ)_/¯\n             */\n            const attr = Array.from(target.attributes).find((attr) => (attr || {}).name === 'href');\n            return { raw: attr?.nodeValue || '' };\n        }\n    };\n\n    // Because even the fallback can crash on IE11/Edge\n    try {\n        return extract();\n    } catch (e: any) {\n        return { raw: '' };\n    }\n};\n\nexport const useLinkHandler: UseLinkHandler = (\n    wrapperRef,\n    mailSettings,\n    { onMailTo, startListening, isOutside, isPhishingAttempt } = defaultOptions\n) => {\n    const { createNotification } = useNotifications();\n    const [link, setLink] = useState<string>();\n    const [linkConfirmationModalProps, setLinkConfirmationModalOpen] = useModalState();\n\n    // eslint-disable-next-line @typescript-eslint/no-misused-promises\n    const handleClick = useHandler(async (event: Event) => {\n        const originalTarget = event.target as Element;\n        const target = originalTarget.closest('a');\n\n        if (!target) {\n            return;\n        }\n\n        const src = getSrc(target);\n\n        if (!src.raw) {\n            createNotification({\n                text: c('Error')\n                    .t`This message may contain some links URL that cannot be properly opened by your current browser.`,\n                type: 'error',\n            });\n        }\n\n        // IE11 and Edge random env bug... (╯°□°）╯︵ ┻━┻\n        if (!src) {\n            event.preventDefault();\n            return false;\n        }\n\n        // We only handle anchor that begins with `mailto:`\n        if (src.raw.toLowerCase().startsWith('mailto:') && onMailTo) {\n            event.preventDefault();\n            event.stopPropagation(); // Required for Safari\n\n            /*\n             * Open the composer with the given mailto address\n             * position isAfter true as the user can choose to set a body\n             */\n            onMailTo(src.raw);\n        }\n\n        const askForConfirmation = mailSettings?.ConfirmLink === undefined ? 1 : mailSettings?.ConfirmLink;\n        const hostname = getHostname(src.raw);\n        const currentDomain = getSecondLevelDomain(window.location.hostname);\n\n        /*\n         * If the modal is already active --- do nothing\n         * ex: click on a link, open the modal, inside the continue button is an anchor with the same link.\n         */\n        if (linkConfirmationModalProps.open) {\n            return;\n        }\n\n        /*\n         * If dealing with anchors, we need to treat them separately because we use URLs with # for searching elements\n         */\n        if (src.raw.startsWith('#')) {\n            const id = src.raw.replace('#', '');\n            if (wrapperRef.current) {\n                const elementInMail = wrapperRef.current.querySelector(`a[name=\"${id}\"], a[id=\"${id}\"]`);\n                if (elementInMail) {\n                    elementInMail.scrollIntoView({ behavior: 'smooth', block: 'start' });\n                }\n            }\n            event.preventDefault();\n            event.stopPropagation();\n            return;\n        }\n\n        if (\n            (askForConfirmation || isPhishingAttempt) &&\n            isExternal(src.raw) &&\n            ![...PROTON_DOMAINS, currentDomain]\n                .filter(isTruthy) // currentDomain can be null\n                .some((domain) => isSubDomain(hostname, domain))\n        ) {\n            event.preventDefault();\n            event.stopPropagation(); // Required for Safari\n\n            const link = punycodeUrl(src.encoded || src.raw);\n            setLink(link);\n            setLinkConfirmationModalOpen(true);\n        }\n    });\n\n    useEffect(() => {\n        if (startListening === false) {\n            return;\n        }\n\n        // eslint-disable-next-line @typescript-eslint/no-misused-promises\n        wrapperRef.current?.addEventListener('click', handleClick, false);\n        return () => {\n            // eslint-disable-next-line @typescript-eslint/no-misused-promises\n            wrapperRef.current?.removeEventListener('click', handleClick, false);\n        };\n    }, [startListening, wrapperRef.current]);\n\n    const modal = (\n        <LinkConfirmationModal\n            link={link}\n            isOutside={isOutside}\n            isPhishingAttempt={isPhishingAttempt}\n            modalProps={linkConfirmationModalProps}\n        />\n    );\n\n    return { modal };\n};\n","import { useCallback } from 'react';\n\nimport { MailSettings as tsMailSettings } from '@proton/shared/lib/interfaces';\nimport { MailSettingsModel } from '@proton/shared/lib/models';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult, { getPromiseValue } from './useCachedModelResult';\n\nexport const useGetMailSettings = (): (() => Promise<tsMailSettings>) => {\n    const api = useApi();\n    const cache = useCache();\n    return useCallback(() => {\n        return getPromiseValue(cache, MailSettingsModel.key, () => MailSettingsModel.get(api));\n    }, [cache, api]);\n};\n\nexport const useMailSettings = (): [tsMailSettings | undefined, boolean, any] => {\n    const cache = useCache();\n    const miss = useGetMailSettings();\n    return useCachedModelResult(cache, MailSettingsModel.key, miss);\n};\n","import { useCallback } from 'react';\n\nimport { LabelCount } from '@proton/shared/lib/interfaces/Label';\nimport { MessageCountsModel } from '@proton/shared/lib/models/messageCountsModel';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult, { getPromiseValue } from './useCachedModelResult';\n\nexport const useGetMessageCounts = (): (() => Promise<LabelCount[]>) => {\n    const api = useApi();\n    const cache = useCache();\n    const miss = useCallback(() => MessageCountsModel.get(api), [api]);\n    return useCallback(() => {\n        return getPromiseValue(cache, MessageCountsModel.key, miss);\n    }, [cache, miss]);\n};\n\nexport const useMessageCounts = (): [LabelCount[], boolean, any] => {\n    const cache = useCache();\n    const miss = useGetMessageCounts();\n    return useCachedModelResult(cache, MessageCountsModel.key, miss);\n};\n","import { useEffect, useState } from 'react';\n\nconst useToggle = (initialState = false) => {\n    const [state, setState] = useState(initialState);\n    const toggle = () => setState(!state);\n\n    useEffect(() => {\n        setState(initialState);\n    }, [initialState]);\n\n    return {\n        state,\n        toggle,\n        set: setState,\n    };\n};\n\nexport default useToggle;\n","export const getAttachment = (attachmentID: string) => ({\n    method: 'get',\n    url: `mail/v4/attachments/${attachmentID}`,\n    output: 'arrayBuffer',\n});\n\nexport const uploadAttachment = (data: {\n    Filename: string;\n    MessageID: string;\n    ContentID: string;\n    MIMEType: string;\n    KeyPackets: Blob;\n    DataPacket: Blob;\n    Signature?: Blob;\n}) => ({\n    method: 'post',\n    url: 'mail/v4/attachments',\n    input: 'form',\n    data,\n});\n\nexport const removeAttachment = (attachmentID: string, messageID: string) => ({\n    method: 'delete',\n    url: `mail/v4/attachments/${attachmentID}`,\n    params: { MessageID: messageID },\n});\n","export const getEOToken = (id: string) => ({\n    method: 'get',\n    url: `mail/v4/eo/token/${id}`,\n});\n\nexport const getEOMessage = (decryptedToken: string, id: string) => ({\n    method: 'get',\n    url: `mail/v4/eo/message`,\n    headers: {\n        Authorization: decryptedToken,\n        'x-eo-uid': id,\n    },\n});\n\nexport const getEOAttachment = (attachmentId: string, decryptedToken: string, id: string) => ({\n    method: 'get',\n    url: `mail/v4/eo/attachment/${attachmentId}`,\n    headers: {\n        Authorization: decryptedToken,\n        'x-eo-uid': id,\n    },\n    output: 'arrayBuffer',\n});\n\nexport const EOReply = (\n    decryptedToken: string,\n    id: string,\n    data: {\n        Body: string;\n        ReplyBody: string;\n        'Filename[]': string[];\n        'MIMEType[]': string[];\n        'ContentID[]': string[];\n        'KeyPackets[]': Blob[];\n        'DataPacket[]': Blob[];\n    }\n) => ({\n    method: 'post',\n    url: 'mail/v4/eo/reply',\n    input: 'form',\n    headers: {\n        Authorization: decryptedToken,\n        'x-eo-uid': id,\n    },\n    data,\n});\n","export const getImage = (Url: string, DryRun = 0, UID?: string) => ({\n    method: 'get',\n    url: 'core/v4/images',\n    params: { Url, DryRun, UID },\n});\n\nexport type SenderImageMode = 'light' | 'dark';\n\n/**\n * Get logo corresponding to address\n * @param Address encoded email address\n * @param Size The size of the logo to be returned, default 48\n * @returns\n */\nexport const getLogo = (\n    Address: string,\n    Size?: number,\n    BimiSelector?: string,\n    Mode?: SenderImageMode,\n    UID?: string\n) => ({\n    method: 'get',\n    url: 'core/v4/images/logo',\n    params: { UID, Address, Size, BimiSelector, Mode },\n});\n","export const undoActions = (Token: string) => ({\n    url: 'mail/v4/undoactions',\n    method: 'post',\n    data: { Token },\n});\n","// BACK-END DATA\nimport { BASE_SIZE } from '../constants';\n\nexport const VCARD_KEY_FIELDS = [\n    'key',\n    'x-pm-mimetype',\n    'x-pm-encrypt',\n    'x-pm-encrypt-untrusted',\n    'x-pm-sign',\n    'x-pm-scheme',\n    'x-pm-tls',\n];\nexport const CLEAR_FIELDS = ['version', 'prodid', 'categories'];\nexport const SIGNED_FIELDS = ['version', 'prodid', 'fn', 'uid', 'email'].concat(VCARD_KEY_FIELDS);\n\nexport enum CRYPTO_PROCESSING_TYPES {\n    SUCCESS,\n    SIGNATURE_NOT_VERIFIED,\n    FAIL_TO_READ,\n    FAIL_TO_LOAD,\n    FAIL_TO_DECRYPT,\n}\n\nexport enum OVERWRITE {\n    // when UID conflict at contact import\n    THROW_ERROR_IF_CONFLICT = 0,\n    OVERWRITE_CONTACT = 1,\n}\n\nexport enum CATEGORIES {\n    IGNORE = 0,\n    INCLUDE = 1,\n}\n\nexport const OTHER_INFORMATION_FIELDS = [\n    'bday',\n    'anniversary',\n    'gender',\n    'lang',\n    'tz',\n    'geo',\n    'title',\n    'role',\n    'photo',\n    'logo',\n    'org',\n    'member',\n    'note',\n    'url',\n];\n\nexport enum PGP_SCHEME_TEXT {\n    INLINE = 'PGP/Inline',\n    MIME = 'PGP/MIME',\n}\n\nexport enum ADDRESS_COMPONENTS {\n    POST_BOX,\n    EXTENDED,\n    STREET,\n    LOCALITY,\n    REGION,\n    POSTAL_CODE,\n    COUNTRY,\n}\n\nexport const CONTACT_IMG_SIZE = 180;\n\nexport const API_SAFE_INTERVAL = 100; // API request limit: 100 requests / 10 seconds, so 1 request every 100 ms is safe\nexport const QUERY_EXPORT_MAX_PAGESIZE = 50; // in GET API route /contacts/export\n// Manual limit on number of imported contacts to be sent to the API, so that the response does not take too long\nexport const ADD_CONTACTS_MAX_SIZE = 10;\n\n// FRONT-END RESTRICTIONS\nexport const MAX_SIMULTANEOUS_CONTACTS_ENCRYPT = 5;\n\nexport const MAX_IMPORT_CONTACTS = 10000;\nexport const MAX_IMPORT_CONTACTS_STRING = MAX_IMPORT_CONTACTS.toLocaleString();\nexport const MAX_IMPORT_FILE_SIZE = 10 * BASE_SIZE ** 2;\nexport const MAX_IMPORT_FILE_SIZE_STRING = '10 MB';\nexport const MAX_CONTACT_ID_CHARS_DISPLAY = 40;\nexport const MAX_FILENAME_CHARS_DISPLAY = 100;\nexport const CONTACT_NAME_MAX_LENGTH = 190;\n\nexport const UID_PREFIX = 'contact-property';\n","import { c } from 'ttag';\n\nimport { CryptoProxy, VERIFICATION_STATUS } from '@proton/crypto';\n\nimport { CONTACT_CARD_TYPE } from '../constants';\nimport { KeysPair } from '../interfaces';\nimport { Contact, ContactCard } from '../interfaces/contacts';\nimport { VCardContact } from '../interfaces/contacts/VCard';\nimport { CRYPTO_PROCESSING_TYPES } from './constants';\nimport { mergeVCard } from './properties';\nimport { parseToVCard } from './vcard';\n\nconst { SUCCESS, SIGNATURE_NOT_VERIFIED, FAIL_TO_READ, FAIL_TO_DECRYPT } = CRYPTO_PROCESSING_TYPES;\n\nconst { CLEAR_TEXT, ENCRYPTED_AND_SIGNED, ENCRYPTED, SIGNED } = CONTACT_CARD_TYPE;\n\nexport interface CryptoProcessingError {\n    type: Exclude<CRYPTO_PROCESSING_TYPES, CRYPTO_PROCESSING_TYPES.SUCCESS>;\n    error: Error;\n}\n\ninterface ProcessedContactData {\n    type: CRYPTO_PROCESSING_TYPES;\n    data?: string;\n    signatureTimestamp?: Date;\n    error?: Error;\n}\n\nexport const decrypt = async ({ Data }: ContactCard, { privateKeys }: Pick<KeysPair, 'privateKeys'>) => {\n    try {\n        const { data } = await CryptoProxy.decryptMessage({ armoredMessage: Data, decryptionKeys: privateKeys });\n\n        if (data && typeof data !== 'string') {\n            throw new Error('Unknown data');\n        }\n        return { type: SUCCESS, data };\n    } catch (error: any) {\n        return { type: FAIL_TO_DECRYPT, error };\n    }\n};\n\nexport const readSigned = async (\n    { Data, Signature = '' }: ContactCard,\n    { publicKeys }: Pick<KeysPair, 'publicKeys'>\n) => {\n    try {\n        if (!Signature) {\n            throw new Error(c('Error').t`Missing signature`);\n        }\n        const { verified, signatureTimestamp } = await CryptoProxy.verifyMessage({\n            textData: Data,\n            stripTrailingSpaces: true,\n            verificationKeys: publicKeys,\n            armoredSignature: Signature,\n        });\n\n        if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {\n            return {\n                data: Data,\n                type: SIGNATURE_NOT_VERIFIED,\n                signatureTimestamp: undefined,\n                error: new Error(c('Error').t`Contact signature not verified`),\n            };\n        }\n        return { type: SUCCESS, data: Data, signatureTimestamp: signatureTimestamp! };\n    } catch (error: any) {\n        return {\n            type: SIGNATURE_NOT_VERIFIED,\n            data: Data,\n            signatureTimestamp: undefined,\n            error,\n        };\n    }\n};\n\nexport const decryptSigned = async ({ Data, Signature }: ContactCard, { publicKeys, privateKeys }: KeysPair) => {\n    try {\n        const { data, verified } = await CryptoProxy.decryptMessage({\n            armoredMessage: Data,\n            decryptionKeys: privateKeys,\n            verificationKeys: publicKeys,\n            armoredSignature: Signature || undefined,\n        });\n\n        if (data && typeof data !== 'string') {\n            throw new Error('Unknown data');\n        }\n\n        if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {\n            return { data, type: SIGNATURE_NOT_VERIFIED, error: new Error(c('Error').t`Signature not verified`) };\n        }\n\n        return { type: SUCCESS, data };\n    } catch (error: any) {\n        return { type: FAIL_TO_DECRYPT, error };\n    }\n};\n\nconst clearText = ({ Data }: ContactCard) => Promise.resolve({ type: SUCCESS, data: Data });\n\nconst ACTIONS: { [index: number]: (...params: any) => Promise<ProcessedContactData> } = {\n    [ENCRYPTED_AND_SIGNED]: decryptSigned,\n    [SIGNED]: readSigned,\n    [ENCRYPTED]: decrypt,\n    [CLEAR_TEXT]: clearText,\n};\n\nexport const decryptContact = async (\n    contact: Contact,\n    { publicKeys, privateKeys }: KeysPair\n): Promise<{ vcards: string[]; errors: (CryptoProcessingError | Error)[]; isVerified: boolean }> => {\n    const { Cards } = contact;\n    let isVerified = Cards.some(({ Type }) => [SIGNED, ENCRYPTED_AND_SIGNED].includes(Type));\n\n    const decryptedCards = await Promise.all(\n        Cards.map(async (card) => {\n            if (!ACTIONS[card.Type]) {\n                return { type: FAIL_TO_READ, error: new Error('Unknown card type') };\n            }\n            return ACTIONS[card.Type](card, { publicKeys, privateKeys });\n        })\n    );\n\n    // remove UIDs put by mistake in encrypted cards\n    const sanitizedCards = decryptedCards.map((card, i) => {\n        if (![ENCRYPTED_AND_SIGNED, ENCRYPTED].includes(Cards[i].Type) || !card.data) {\n            return card;\n        }\n        return { ...card, data: card.data.replace(/\\nUID:.*\\n/i, '\\n') };\n    });\n\n    const { vcards, errors } = sanitizedCards.reduce<{ vcards: string[]; errors: CryptoProcessingError[] }>(\n        (acc, { type, data, error }) => {\n            if (data) {\n                acc.vcards.push(data);\n            }\n            if (error) {\n                if (type === SUCCESS) {\n                    throw new Error('Inconsistency detected during contact card processing');\n                }\n                if (type === SIGNATURE_NOT_VERIFIED) {\n                    isVerified = false;\n                }\n                acc.errors.push({ type, error });\n            }\n            return acc;\n        },\n        { vcards: [], errors: [] }\n    );\n\n    return { isVerified, vcards, errors };\n};\n\nexport const prepareVCardContact = async (\n    contact: Contact,\n    { publicKeys, privateKeys }: KeysPair\n): Promise<{ vCardContact: VCardContact; errors: (CryptoProcessingError | Error)[]; isVerified: boolean }> => {\n    const { isVerified, vcards, errors } = await decryptContact(contact, { publicKeys, privateKeys });\n\n    try {\n        const vCardContacts = vcards.map((vcard) => parseToVCard(vcard));\n        const vCardContact = mergeVCard(vCardContacts);\n\n        return { vCardContact, errors, isVerified };\n    } catch (e: any) {\n        // eslint-disable-next-line no-console\n        console.error('Error in prepare vCard', e);\n        const error = e instanceof Error ? e : new Error('Corrupted vcard data');\n\n        return { vCardContact: { fn: [] }, errors: [error], isVerified };\n    }\n};\n","import { c } from 'ttag';\n\nimport { CryptoProxy, PrivateKeyReference, PublicKeyReference } from '@proton/crypto';\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport { CONTACT_CARD_TYPE } from '../constants';\nimport { CANONICALIZE_SCHEME, canonicalizeEmail } from '../helpers/email';\nimport { generateProtonWebUID } from '../helpers/uid';\nimport { ContactCard } from '../interfaces/contacts';\nimport { VCardProperty } from '../interfaces/contacts/VCard';\nimport { CRYPTO_PROCESSING_TYPES } from './constants';\nimport { readSigned } from './decrypt';\nimport { toKeyProperty } from './keyProperties';\nimport { createContactPropertyUid, getVCardProperties } from './properties';\nimport { parseToVCard, vCardPropertiesToICAL } from './vcard';\n\n/**\n * Pin a public key in a contact. Give to it the highest preference\n * Public keys need to be passed to check signature validity of signed contact cards\n * Private keys (typically only the primary one) need to be passed to sign the new contact card with the new pinned key\n */\ninterface ParamsUpdate {\n    contactCards: ContactCard[];\n    emailAddress: string;\n    isInternal: boolean;\n    bePinnedPublicKey: PublicKeyReference;\n    publicKeys: PublicKeyReference[];\n    privateKeys: PrivateKeyReference[];\n}\nexport const pinKeyUpdateContact = async ({\n    contactCards,\n    emailAddress,\n    isInternal,\n    bePinnedPublicKey,\n    publicKeys,\n    privateKeys,\n}: ParamsUpdate): Promise<ContactCard[]> => {\n    // get the signed card of the contact that contains the key properties. Throw if there are errors\n    const [signedCard, ...otherCards] = contactCards.reduce<ContactCard[]>((acc, card) => {\n        if (card.Type === CONTACT_CARD_TYPE.SIGNED) {\n            acc.unshift(card);\n        } else {\n            acc.push(card);\n        }\n        return acc;\n    }, []);\n    const readSignedCard = await readSigned(signedCard, { publicKeys });\n    if (readSignedCard.type !== CRYPTO_PROCESSING_TYPES.SUCCESS) {\n        if (readSignedCard.error) {\n            throw readSignedCard.error;\n        }\n        throw new Error('Unknown error');\n    }\n    const signedVcard = readSignedCard.data;\n\n    // get the key properties that correspond to the email address\n    const signedVCard = parseToVCard(signedVcard);\n    const signedProperties = getVCardProperties(signedVCard);\n    const emailProperty = signedProperties.find(({ field, value }) => {\n        const scheme = isInternal ? CANONICALIZE_SCHEME.PROTON : CANONICALIZE_SCHEME.DEFAULT;\n        return (\n            field === 'email' && canonicalizeEmail(value as string, scheme) === canonicalizeEmail(emailAddress, scheme)\n        );\n    });\n    const emailGroup = emailProperty?.group as string;\n    const keyProperties = emailGroup\n        ? signedProperties.filter((prop) => {\n              return prop.field === 'key' && prop.group === emailGroup;\n          })\n        : undefined;\n    if (!keyProperties) {\n        throw new Error(c('Error').t`The key properties for ${emailAddress} could not be extracted`);\n    }\n\n    // add the new key as the preferred one\n    const shiftedPrefKeyProperties = keyProperties.map((property) => ({\n        ...property,\n        params: {\n            ...property.params,\n            pref: String(Number(property.params?.pref) + 1),\n        },\n    }));\n    const newKeyProperties = [\n        await toKeyProperty({ publicKey: bePinnedPublicKey, group: emailGroup, index: 0 }),\n        ...shiftedPrefKeyProperties,\n    ];\n    const untouchedSignedProperties = signedProperties.filter(\n        ({ field, group }) => field !== 'key' || group !== emailGroup\n    );\n    const newSignedProperties = [...untouchedSignedProperties, ...newKeyProperties];\n\n    // sign the new properties\n    const toSignVcard: string = vCardPropertiesToICAL(newSignedProperties).toString();\n    const signature = await CryptoProxy.signMessage({\n        textData: toSignVcard,\n        stripTrailingSpaces: true,\n        signingKeys: privateKeys,\n        detached: true,\n    });\n    const newSignedCard = {\n        Type: CONTACT_CARD_TYPE.SIGNED,\n        Data: toSignVcard,\n        Signature: signature,\n    };\n    return [newSignedCard, ...otherCards];\n};\n\n/**\n * Create a contact with a pinned key. Set encrypt flag to true\n * Private keys (typically only the primary one) need to be passed to sign the new contact card with the new pinned key\n */\ninterface ParamsCreate {\n    emailAddress: string;\n    name?: string;\n    isInternal: boolean;\n    bePinnedPublicKey: PublicKeyReference;\n    privateKeys: PrivateKeyReference[];\n}\nexport const pinKeyCreateContact = async ({\n    emailAddress,\n    name,\n    isInternal,\n    bePinnedPublicKey,\n    privateKeys,\n}: ParamsCreate): Promise<ContactCard[]> => {\n    const properties: VCardProperty[] = [\n        { field: 'fn', value: name || emailAddress, uid: createContactPropertyUid() },\n        { field: 'uid', value: generateProtonWebUID(), uid: createContactPropertyUid() },\n        { field: 'email', value: emailAddress, group: 'item1', uid: createContactPropertyUid() },\n        !isInternal && { field: 'x-pm-encrypt', value: 'true', group: 'item1', uid: createContactPropertyUid() },\n        !isInternal && { field: 'x-pm-sign', value: 'true', group: 'item1', uid: createContactPropertyUid() },\n        await toKeyProperty({ publicKey: bePinnedPublicKey, group: 'item1', index: 0 }),\n    ].filter(isTruthy);\n    // sign the properties\n    const toSignVcard: string = vCardPropertiesToICAL(properties).toString();\n    const signature = await CryptoProxy.signMessage({\n        textData: toSignVcard,\n        stripTrailingSpaces: true,\n        signingKeys: privateKeys,\n        detached: true,\n    });\n    const newSignedCard = {\n        Type: CONTACT_CARD_TYPE.SIGNED,\n        Data: toSignVcard,\n        Signature: signature,\n    };\n    return [newSignedCard];\n};\n","import { CryptoProxy, PublicKeyReference } from '@proton/crypto';\nimport { arrayToBinaryString, binaryStringToArray, decodeBase64, encodeBase64 } from '@proton/crypto/lib/utils';\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport { MIME_TYPES, PGP_SCHEMES } from '../constants';\nimport { MimeTypeVcard, PinnedKeysConfig } from '../interfaces';\nimport { VCardContact, VCardProperty } from '../interfaces/contacts/VCard';\nimport { compareVCardPropertyByPref, createContactPropertyUid } from './properties';\n\n/**\n * The only values allowed for a PGP scheme stored in a vCard are\n * '' for default PGP scheme (meaning we should use the PGPScheme from mailSettings when composing email)\n * 'pgp-mime' for PGP-Inline scheme\n * 'pgp-mime' for PGP-MIME scheme\n */\nexport const getPGPSchemeVcard = (scheme: string): PGP_SCHEMES | undefined => {\n    // ugly code; typescript to be blamed\n    if (Object.values(PGP_SCHEMES).includes(scheme as PGP_SCHEMES)) {\n        return scheme as PGP_SCHEMES;\n    }\n    return undefined;\n};\n/**\n * The only values allowed for a MIME type stored in a vCard are\n * '' for automatic format (meaning we should use DraftMIMEType from mailSettings when composing email)\n * 'text/plain' for plain text format\n */\nexport const getMimeTypeVcard = (mimeType: string): MimeTypeVcard | undefined => {\n    return mimeType === MIME_TYPES.PLAINTEXT ? mimeType : undefined;\n};\n\nexport const getKeyVCard = async (keyValue: string): Promise<PublicKeyReference | undefined> => {\n    const [, base64 = ''] = keyValue.split(',');\n    const key = binaryStringToArray(decodeBase64(base64));\n\n    if (key.length) {\n        const publicKey = await CryptoProxy.importPublicKey({ binaryKey: key });\n        return publicKey;\n    }\n};\n\n/**\n * Given an array of vCard properties, extract the keys and key-related fields relevant for an email address\n */\nexport const getKeyInfoFromProperties = async (\n    vCardContact: VCardContact,\n    emailGroup: string\n): Promise<Omit<PinnedKeysConfig, 'isContactSignatureVerified' | 'isContact'>> => {\n    const getByGroup = <T>(properties: VCardProperty<T>[] = []): VCardProperty<T> | undefined =>\n        properties.find(({ group }) => group === emailGroup);\n\n    const pinnedKeyPromises = (vCardContact.key || [])\n        .filter(({ group }) => group === emailGroup)\n        .sort(compareVCardPropertyByPref)\n        .map(async ({ value }) => getKeyVCard(value));\n    const pinnedKeys = (await Promise.all(pinnedKeyPromises)).filter(isTruthy);\n    const encryptToPinned = getByGroup(vCardContact['x-pm-encrypt'])?.value;\n    const encryptToUntrusted = getByGroup(vCardContact['x-pm-encrypt-untrusted'])?.value;\n    const scheme = getByGroup(vCardContact['x-pm-scheme'])?.value;\n    const mimeType = getByGroup(vCardContact['x-pm-mimetype'])?.value;\n    const sign = getByGroup(vCardContact['x-pm-sign'])?.value;\n\n    return { pinnedKeys, encryptToPinned, encryptToUntrusted, scheme, mimeType, sign };\n};\n\ninterface VcardPublicKey {\n    publicKey: PublicKeyReference;\n    group: string;\n    index: number;\n}\n\n/**\n * Transform a key into a vCard property\n */\nexport const toKeyProperty = async ({ publicKey, group, index }: VcardPublicKey): Promise<VCardProperty<string>> => {\n    const binaryKey = await CryptoProxy.exportPublicKey({ key: publicKey, format: 'binary' });\n    return {\n        field: 'key',\n        value: `data:application/pgp-keys;base64,${encodeBase64(arrayToBinaryString(binaryKey))}`,\n        group,\n        params: { pref: String(index + 1) }, // order is important\n        uid: createContactPropertyUid(),\n    };\n};\n","import generateUID from '../helpers/generateUID';\nimport { ContactValue } from '../interfaces/contacts';\nimport { VCardContact, VCardProperty } from '../interfaces/contacts/VCard';\nimport { UID_PREFIX } from './constants';\nimport { isMultiValue } from './vcard';\n\nexport const FIELDS_WITH_PREF = ['fn', 'email', 'tel', 'adr', 'key', 'photo'];\n\nexport const getStringContactValue = (value: ContactValue): string => {\n    if (Array.isArray(value)) {\n        return getStringContactValue(value[0]);\n    }\n    // Shouldnt really happen but some boolean gets there as boolean instead of strings\n    return String(value);\n};\n\n/**\n * Given a vCard field, return true if we take into consideration its PREF parameters\n */\nexport const hasPref = (field: string) => FIELDS_WITH_PREF.includes(field);\n\n/**\n * For a vCard contact, check if it contains categories\n */\nexport const hasCategories = (vcardContact: VCardProperty[]) => {\n    return vcardContact.some(({ field, value }) => value && field === 'categories');\n};\n\n/**\n * Extract categories from a vCard contact\n */\nexport const getContactCategories = (contact: VCardContact) => {\n    return (contact.categories || [])\n        .map(({ value, group }) => {\n            if (Array.isArray(value)) {\n                return group\n                    ? value.map((singleValue) => ({ name: getStringContactValue(singleValue), group }))\n                    : value.map((singleValue) => ({ name: getStringContactValue(singleValue) }));\n            }\n            return group ? { name: value, group } : { name: value };\n        })\n        .flat();\n};\n\n/**\n * Generate new group name that doesn't exist\n */\nexport const generateNewGroupName = (existingGroups: string[] = []): string => {\n    let index = 1;\n    let found = false;\n\n    while (!found) {\n        if (existingGroups.includes(`item${index}`)) {\n            index++;\n        } else {\n            found = true;\n        }\n    }\n\n    return `item${index}`;\n};\n\n/**\n * Extract emails from a vCard contact\n */\nexport const getContactEmails = (contact: VCardContact) => {\n    return (contact.email || []).map(({ value, group }) => {\n        if (!group) {\n            throw new Error('Email properties should have a group');\n        }\n        return {\n            email: getStringContactValue(value),\n            group,\n        };\n    });\n};\n\nexport const createContactPropertyUid = () => generateUID(UID_PREFIX);\n\nexport const getContactPropertyUid = (uid: string) => Number(uid.replace(`${UID_PREFIX}-`, ''));\n\n// TODO: Deprecate this function. See VcardProperty interface\nexport const getVCardProperties = (vCardContact: VCardContact): VCardProperty[] => {\n    return Object.values(vCardContact).flatMap((property) => {\n        if (Array.isArray(property)) {\n            return property;\n        } else {\n            return [property];\n        }\n    });\n};\n\nexport const fromVCardProperties = (vCardProperties: VCardProperty[]): VCardContact => {\n    const vCardContact = {} as VCardContact;\n\n    vCardProperties.forEach((property) => {\n        const field = property.field as keyof VCardContact;\n\n        if (isMultiValue(field)) {\n            if (!vCardContact[field]) {\n                vCardContact[field] = [] as any;\n            }\n            (vCardContact[field] as VCardProperty[]).push(property);\n        } else {\n            vCardContact[field] = property as any;\n        }\n    });\n\n    return vCardContact;\n};\n\nexport const mergeVCard = (vCardContacts: VCardContact[]): VCardContact => {\n    return fromVCardProperties(vCardContacts.flatMap(getVCardProperties));\n};\n\nexport const updateVCardContact = (vCardContact